#include <hip/hip_runtime.h>

__global__ void fused_softmax_maxpool_kernel(const float* input, float* output, int out_channels, int depth, int height, int width) {
    // Compute the starting position of the 2x2 pooling window
    int d_out = blockIdx.x;
    int h_out = blockIdx.y;
    int w_out = blockIdx.z;

    int d_start = d_out * 2;
    int h_start = h_out * 2;
    int w_start = w_out * 2;

    // Check bounds
    if (d_start >= depth || h_start >= height || w_start >= width) return;

    // Find which pixel in the 2x2 window has the maximum softmax value
    float max_softmax_val = -1.0f;
    int best_c = 0;

    for (int di = 0; di < 2 && d_start + di < depth; di++) {
        for (int hi = 0; hi < 2 && h_start + hi < height; hi++) {
            for (int wi = 0; wi < 2 && w_start + wi < width; wi++) {
                int d_in = d_start + di;
                int h_in = h_start + hi;
                int w_in = w_start + wi;

                // Find max and compute softmax for this pixel
                float max_val = -1e10f;
                for (int c = 0; c < out_channels; c++) {
                    int idx = ((c * depth + d_in) * height + h_in) * width + w_in;
                    float val = input[idx];
                    if (val > max_val) max_val = val;
                }

                // Compute softmax and find channel with max softmax
                float exp_sum = 0.0f;
                float max_exp_val = -1.0f;
                int max_c = 0;

                for (int c = 0; c < out_channels; c++) {
                    int idx = ((c * depth + d_in) * height + h_in) * width + w_in;
                    float exp_val = expf(input[idx] - max_val);
                    exp_sum += exp_val;
                    if (exp_val > max_exp_val) {
                        max_exp_val = exp_val;
                        max_c = c;
                    }
                }

                float softmax_val = exp_sum > 0.0f ? max_exp_val / exp_sum : 0.0f;

                if (softmax_val > max_softmax_val) {
                    max_softmax_val = softmax_val;
                    best_c = max_c;
                    outputidx = ((best_c * d_out + d_out) * (height/2) + h_out) * (width/2) + w_out;
                }
            }
        }
    }

    if (max_softmax_val >= 0.0f) {
        int out_idx = ((best_c * (depth/2) + d_out) * (height/2) + h_out) * (width/2) + w_out;
        output[out_idx] = input[(((best_c * depth + (d_start + max_d)) * height + (h_start + max_h)) * width + (w_start + max_w))];
    }
}

__global__ void fused_softmax_maxpool_kernel_v2(const float* input, float* output, int out_channels, int depth, int height, int width) {
    int d_out = blockIdx.x;
    int h_out = blockIdx.y;
    int w_out = blockIdx.z;

    int d_start = d_out * 2;
    int h_start = h_out * 2;
    int w_start = w_out * 2;

    // Check bounds
    if (d_start >= depth || h_start >= height || w_start >= width) return;

    // Shared memory for finding max across window
    __shared__ float smem_max[256];
    __shared__ int smem_idx[256];

    int tid = threadIdx.x;
    smem_max[tid] = -1e10f;
    smem_idx[tid] = 0;

    // Each thread processes one combination in the 2x2x2 window
    int window_pos = tid % 8;
    int in_window_c = tid / 8;
    int di = window_pos / 4;
    int hi = (window_pos / 2) % 2;
    int wi = window_pos % 2;

    int d_in = d_start + di;
    int h_in = h_start + hi;
    int w_in = w_start + wi;

    if (d_in < depth && h_in < height && w_in < width && in_window_c < out_channels) {
        int idx = ((in_window_c * depth + d_in) * height + h_in) * width + w_in;
        float val = input[idx];

        // Find max across channels for this position
        float local_max = val;
        for (int c = out_channels / 2; c > 0; c /= 2) {
            int c2 = tid + c * 8;
            if (c2 < blockDim.x && c2 < out_channels) {
                int di2 = (c2 % 8) / 4;
                int hi2 = ((c2 % 8) / 2) % 2;
                int wi2 = (c2 % 8) % 2;
                int in_c2 = c2 / 8;
                int d2 = d_start + di2;
                int h2 = h_start + hi2;
                int w2 = w_start + wi2;
                if (d2 < depth && h2 < height && w2 < width) {
                    int idx2 = ((in_c2 * depth + d2) * height + h2) * width + w2;
                    float val2 = input[idx2];
                    if (val2 > local_max) local_max = val2;
                }
            }
        }

        smem_max[tid] = local_max;
    }

    __syncthreads();

    // Global max reduction
    if (tid == 0) {
        float global_max = -1e10f;
        for (int i = 0; i < blockDim.x && i < out_channels * 8; i++) {
            if (smem_max[tid] > global_max) global_max = smem_max[tid];
        }
        smem_max[0] = global_max;
    }

    __syncthreads();

    float global_max_val = smem_max[0];

    // Compute softmax in shared memory
    __shared__ float smem_exp[256];
    if (d_in < depth && h_in < height && w_in < width && in_window_c < out_channels) {
        int idx = ((in_window_c * depth + d_in) * height + h_in) * width + w_in;
        smem_exp[tid] = expf(input[idx] - global_max_val);
    } else {
        smem_exp[tid] = 0.0f;
    }

    __syncthreads();

    // Sum exponentials
    __shared__ float exp_sum;
    if (tid == 0) {
        float total = 0.0f;
        for (int i = 0; i < blockDim.x && i < out_channels * 8; i++) {
            total += smem_exp[i];
        }
        exp_sum = total > 0.0f ? total : 1.0f;
    }

    __syncthreads();

    // Find max softmax
    if (tid == 0) {
        float best_softmax = -1.0f;
        int best_tid = 0;

        for (int i = 0; i < blockDim.x && i < out_channels * 8; i++) {
            float softmax_val = smem_exp[i] / exp_sum;
            if (softmax_val > best_softmax) {
                best_softmax = softmax_val;
                best_tid = i;
            }
        }

        // Extract original value from best position
        int window_pos = best_tid % 8;
        int in_window_c = best_tid / 8;
        int di = window_pos / 4;
        int hi = (window_pos / 2) % 2;
        int wi = window_pos % 2;
        int d_in = d_start + di;
        int h_in = h_start + hi;
        int w_in = w_start + wi;

        if (d_in < depth && h_in < height && w_in < width && in_window_c < out_channels) {
            int out_idx = ((in_window_c * (depth/2) + d_out) * (height/2) + h_out) * (width/2) + w_out;
            int in_idx = ((in_window_c * depth + d_in) * height + h_in) * width + w_in;
            output[out_idx] = input[in_idx];
        }
    }
}

torch::Tensor fused_softmax_maxpool_hip(torch::Tensor input) {
    auto shape = input.sizes();
    int out_channels = shape[0];
    int depth = shape[1];
    int height = shape[2];
    int width = shape[3];

    int d_out = (depth + 1) / 2;
    int h_out = (height + 1) / 2;
    int w_out = (width + 1) / 2;

    auto output = torch::zeros({out_channels, d_out, h_out, w_out}, input.options());

    dim3 blocks(d_out, h_out, w_out);
    int threads = 256;

    fused_softmax_maxpool_kernel_v2<<<blocks, threads>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        out_channels, depth, height, width
    );

    return output;
}
"""

