#include <hip/hip_runtime.h>

__global__ void fused_double_maxpool_kernel(const float* input, float* output, 
                                           int channels, int depth, int height, int width,
                                           int out_depth, int out_height, int out_width) {
    int d_out = blockIdx.x;
    int h_out = blockIdx.y;
    int w_out = blockIdx.z;
    int c = threadIdx.x;

    if (d_out >= out_depth || h_out >= out_height || w_out >= out_width || c >= channels) return;

    // Two 2x2 pools -> effectively 4x4 window, but need to respect floor behavior
    int d_start = d_out * 4;
    int h_start = h_out * 4;
    int w_start = w_out * 4;

    float max_val = -1e10f;

    // Limit search area to valid region (handle boundary)
    int d_end = min(d_start + 4, depth);
    int h_end = min(h_start + 4, height);
    int w_end = min(w_start + 4, width);

    for (int di = d_start; di < d_end; di++) {
        for (int hi = h_start; hi < h_end; hi++) {
            for (int wi = w_start; wi < w_end; wi++) {
                int idx = ((c * depth + di) * height + hi) * width + wi;
                float val = input[idx];
                if (val > max_val) max_val = val;
            }
        }
    }

    // Output is compressed: floor(floor(dim/2)/2)
    int out_idx = ((c * out_depth + d_out) * out_height + h_out) * out_width + w_out;
    output[out_idx] = max_val;
}

torch::Tensor fused_double_maxpool_hip(torch::Tensor input) {
    int channels = input.size(0);
    int depth = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    // After two 2x2 pools: floor(floor(dim/2)/2)
    int pool1_depth = depth / 2;
    int pool1_height = height / 2;
    int pool1_width = width / 2;

    int out_depth = pool1_depth / 2;
    int out_height = pool1_height / 2;
    int out_width = pool1_width / 2;

    auto output = torch::zeros({channels, out_depth, out_height, out_width}, input.options());

    dim3 blocks(out_depth, out_height, out_width);
    dim3 threads(channels);

    if (channels > 0) {
        fused_double_maxpool_kernel<<<blocks, threads>>>(
            input.data_ptr<float>(), 
            output.data_ptr<float>(), 
            channels, depth, height, width,
            out_depth, out_height, out_width
        );
    }

    return output;
}
"""

