class ModelNew(nn.Module):
    """
    Model that performs a 3D convolution, applies fused Softmax+MaxPool, and a second max pooling operation.
    """
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.fused_softmax_maxpool = fused_softmax_maxpool
        self.pool2 = nn.MaxPool3d(pool_kernel_size)

    def forward(self, x):
        """
        Args:
            x: Input tensor of shape (batch_size, in_channels, depth, height, width)
        Returns:
            Output tensor of shape (batch_size, out_channels, depth', height', width')
        """
        x = self.conv(x)

        # Reshape for fused kernel: flatten batch into channels, handle 5D to 4D
        b, c, d, h, w = x.shape
        x_reshaped = x.permute(0, 2, 3, 4, 1).contiguous()  # (b, d, h, w, c)
        x_reshaped = x_reshaped.view(-1, d, h, w)  # (b*d*h*w, c?) - wait, this isn't right

        # Actually need to handle each batch element's spatial volume separately
        # For now, apply fused operation per batch element
        outputs = []
        for i in range(b):
            batch_input = x[i]  # (c, d, h, w)
            batch_output = self.fused_softmax_maxpool.fused_softmax_maxpool_hip(batch_input)
            outputs.append(batch_output)

        x = torch.stack(outputs, dim=0)  # (b, c, d/2, h/2, w/2)

        # Second pool
        x = self.pool2(x)
        return x


